def matvec(A, v):
    return [A[0][0] * v[0] + A[0][1] * v[1], A[1][0] * v[0] + A[1][1] * v[1]]

def eigenvalue_of(A, v, tol=1e-9):
    w = matvec(A, v)
    if abs(v[0] * w[1] - v[1] * w[0]) > tol:
        return None
    return (w[0] * v[0] + w[1] * v[1]) / (v[0] ** 2 + v[1] ** 2)
